from __future__ import annotations

import os
import uuid
from collections.abc import Callable
from urllib.parse import urlsplit

from fsutil.args import get_path as _get_path
from fsutil.checks import assert_dir, exists
from fsutil.types import PathIn


def get_filename(path: PathIn) -> str:
    """Return the filename portion of a filesystem path or URL."""
    path_str = _get_path(path) or ""
    return os.path.basename(urlsplit(path_str).path)


def split_filename(path: PathIn) -> tuple[str, str]:
    """Split a filename into basename and extension without the leading dot."""
    basename, extension = os.path.splitext(get_filename(path))
    return basename, extension.lstrip(".")


def get_file_basename(path: PathIn) -> str:
    """Return the basename of a filename."""
    return split_filename(path)[0]


def get_file_extension(path: PathIn) -> str:
    """Return the extension of a filename without the leading dot."""
    return split_filename(path)[1]


def join_filename(basename: str, extension: str) -> str:
    """Join basename and extension into a filename."""
    clean_basename = basename.rstrip(".").strip()
    clean_extension = extension.lstrip(".").strip()
    if clean_basename and clean_extension:
        return f"{clean_basename}.{clean_extension}"
    return clean_basename or clean_extension


def split_filepath(path: PathIn) -> tuple[str, str]:
    """Split a path into directory path and filename."""
    path_str = _get_path(path) or ""
    return os.path.dirname(path_str), get_filename(path_str)


def join_filepath(dirpath: PathIn, filename: str) -> str:
    """Join a directory path and filename into a filepath."""
    return join_path(dirpath, filename)


def split_path(path: PathIn) -> list[str]:
    """Split a path into path components."""
    path_str = _get_path(path) or ""
    head, tail = os.path.split(path_str)
    parts = head.split(os.sep) + [tail]
    return [part for part in parts if part]


def join_path(path: PathIn, *paths: PathIn) -> str:
    """Join one or more path components and normalize the result."""
    base = _get_path(path) or ""
    if get_file_extension(base) in {"py", "pyc", "pyo"}:
        base = os.path.dirname(os.path.realpath(base))
    extra = [(_get_path(item) or "").lstrip("/\\") for item in paths]
    return os.path.normpath(os.path.join(base, *extra))


def get_parent_dir(path: PathIn, *, levels: int = 1) -> str:
    """Return the parent directory path after walking up ``levels`` times."""
    return join_path(path, *([os.pardir] * max(1, levels)))


def get_unique_name(
    path: PathIn,
    *,
    prefix: str = "",
    suffix: str = "",
    extension: str = "",
    separator: str = "-",
) -> str:
    """Return a unique filename for the given existing directory."""
    path_str = _get_path(path) or ""
    assert_dir(path_str)
    while True:
        parts = []
        if prefix:
            parts.append(prefix)
        parts.append(str(uuid.uuid4()))
        if suffix:
            parts.append(suffix)
        filename = separator.join(parts)
        if extension:
            filename = f"{filename}.{extension.lstrip('.')}"
        if not exists(join_path(path_str, filename)):
            return filename


def transform_filepath(
    path: PathIn,
    *,
    dirpath: str | Callable[[str], str] | None = None,
    basename: str | Callable[[str], str] | None = None,
    extension: str | Callable[[str], str] | None = None,
) -> str:
    """Return a filepath with selected path components transformed."""

    def _resolve(
        candidate: str | Callable[[str], str] | None,
        current: str,
    ) -> str:
        if candidate is None:
            return current
        return candidate(current) if callable(candidate) else candidate

    if all(value is None for value in (dirpath, basename, extension)):
        raise ValueError(
            "Invalid arguments: at least one of "
            "'dirpath', 'basename' or 'extension' is required."
        )
    current_dirpath, current_filename = split_filepath(path)
    current_basename, current_extension = split_filename(current_filename)
    new_dirpath = _resolve(dirpath, current_dirpath)
    new_basename = _resolve(basename, current_basename)
    new_extension = _resolve(extension, current_extension)
    if not any((new_dirpath, new_basename, new_extension)):
        raise ValueError(
            "Invalid arguments: at least one of "
            "'dirpath', 'basename' or 'extension' is required."
        )
    return join_filepath(new_dirpath, join_filename(new_basename, new_extension))


