from __future__ import annotations

import os

from fsutil.args import get_path as _get_path
from fsutil.types import PathIn


def exists(path: PathIn) -> bool:
    """Return ``True`` when the path exists."""
    return os.path.exists(_get_path(path) or "")


def is_file(path: PathIn) -> bool:
    """Return ``True`` when the path exists and is a file."""
    return os.path.isfile(_get_path(path) or "")


def is_dir(path: PathIn) -> bool:
    """Return ``True`` when the path exists and is a directory."""
    return os.path.isdir(_get_path(path) or "")


def assert_exists(path: PathIn) -> None:
    """Raise ``OSError`` when the path does not exist."""
    path_str = _get_path(path)
    if not exists(path):
        raise OSError(f"Invalid item path: {path_str}")


def assert_file(path: PathIn) -> None:
    """Raise ``OSError`` when the path is not an existing file."""
    path_str = _get_path(path)
    if not is_file(path):
        raise OSError(f"Invalid file path: {path_str}")


def assert_dir(path: PathIn) -> None:
    """Raise ``OSError`` when the path is not an existing directory."""
    path_str = _get_path(path)
    if not is_dir(path):
        raise OSError(f"Invalid directory path: {path_str}")


def assert_not_exists(path: PathIn) -> None:
    """Raise ``OSError`` when the path already exists."""
    path_str = _get_path(path)
    if exists(path):
        raise OSError(f"Invalid path, item already exists: {path_str}")


def assert_not_file(path: PathIn) -> None:
    """Raise ``OSError`` when the path is an existing file."""
    path_str = _get_path(path)
    if is_file(path):
        raise OSError(f"Invalid path, file already exists: {path_str}")


def assert_not_dir(path: PathIn) -> None:
    """Raise ``OSError`` when the path is an existing directory."""
    path_str = _get_path(path)
    if is_dir(path):
        raise OSError(f"Invalid path, directory already exists: {path_str}")


def is_empty_file(path: PathIn) -> bool:
    """Return ``True`` when the file exists and has no content."""
    from fsutil.info import get_file_size

    return get_file_size(path) == 0


def is_empty_dir(path: PathIn) -> bool:
    """Return ``True`` when the directory exists and has no content."""
    path_str = _get_path(path)
    assert_dir(path_str or "")
    return len(os.listdir(path_str or "")) == 0


def is_empty(path: PathIn) -> bool:
    """Return ``True`` when the file or directory exists and is empty."""
    assert_exists(path)
    return is_empty_dir(path) if is_dir(path) else is_empty_file(path)

