from __future__ import annotations

import hashlib
import os
import pathlib
from datetime import datetime
from typing import IO

from fsutil.args import get_path as _get_path
from fsutil.checks import assert_dir, assert_file
from fsutil.converters import convert_size_bytes_to_string
from fsutil.operations import search_files
from fsutil.types import PathIn


def get_dir_creation_date(path: PathIn) -> datetime:
    """Return the creation date of a directory."""
    path_str = _get_path(path) or ""
    assert_dir(path_str)
    return datetime.fromtimestamp(os.path.getctime(path_str))


def get_dir_creation_date_formatted(
    path: PathIn,
    *,
    format: str = "%Y-%m-%d %H:%M:%S",
) -> str:
    """Return the formatted creation date of a directory."""
    return get_dir_creation_date(path).strftime(format)


def get_dir_hash(path: PathIn, *, func: str = "md5") -> str:
    """Return a content hash for all files within a directory tree."""
    path_str = _get_path(path) or ""
    assert_dir(path_str)
    digest = hashlib.new(func)
    for file_path in sorted(search_files(path_str, pattern="**/*")):
        relpath = os.path.relpath(file_path, path_str).replace(os.sep, "/")
        digest.update(relpath.encode("utf-8"))
        digest.update(get_file_hash(file_path, func=func).encode("utf-8"))
    return digest.hexdigest()


def get_dir_last_modified_date(path: PathIn) -> datetime:
    """Return the latest modification date found in a directory tree."""
    path_str = _get_path(path) or ""
    assert_dir(path_str)
    last_modified = os.path.getmtime(path_str)
    for basepath, dirnames, filenames in os.walk(path_str):
        for dirname in dirnames:
            last_modified = max(last_modified, os.path.getmtime(os.path.join(basepath, dirname)))
        for filename in filenames:
            last_modified = max(last_modified, os.path.getmtime(os.path.join(basepath, filename)))
    return datetime.fromtimestamp(last_modified)


def get_dir_last_modified_date_formatted(
    path: PathIn,
    *,
    format: str = "%Y-%m-%d %H:%M:%S",
) -> str:
    """Return the formatted last-modified date of a directory tree."""
    return get_dir_last_modified_date(path).strftime(format)


def get_dir_size(path: PathIn) -> int:
    """Return the total size of regular files within a directory tree."""
    path_str = _get_path(path) or ""
    assert_dir(path_str)
    total = 0
    for basepath, _, filenames in os.walk(path_str):
        for filename in filenames:
            filepath = os.path.join(basepath, filename)
            if not os.path.islink(filepath):
                total += get_file_size(filepath)
    return total


def get_dir_size_formatted(path: PathIn) -> str:
    """Return the directory size using a human-readable unit."""
    return convert_size_bytes_to_string(get_dir_size(path))


def get_file_creation_date(path: PathIn) -> datetime:
    """Return the creation date of a file."""
    path_str = _get_path(path) or ""
    assert_file(path_str)
    return datetime.fromtimestamp(os.path.getctime(path_str))


def get_file_creation_date_formatted(
    path: PathIn,
    *,
    format: str = "%Y-%m-%d %H:%M:%S",
) -> str:
    """Return the formatted creation date of a file."""
    return get_file_creation_date(path).strftime(format)


def get_file_hash(path: PathIn | IO[bytes], *, func: str = "md5") -> str:
    """Return the cryptographic digest of a file path or file-like object."""
    digest = hashlib.new(func)
    if isinstance(path, (str, pathlib.Path, os.PathLike)):
        path_str = _get_path(path) or ""
        assert_file(path_str)
        with open(path_str, "rb") as file_handle:
            for chunk in iter(lambda: file_handle.read(4096), b""):
                digest.update(chunk)
    else:
        fileobj = path
        position: int | None = None
        if fileobj.seekable():
            position = fileobj.tell()
            fileobj.seek(0)
        for chunk in iter(lambda: fileobj.read(4096), b""):
            digest.update(chunk)
        if position is not None:
            fileobj.seek(position)
    return digest.hexdigest()


def get_file_last_modified_date(path: PathIn) -> datetime:
    """Return the last-modified date of a file."""
    path_str = _get_path(path) or ""
    assert_file(path_str)
    return datetime.fromtimestamp(os.path.getmtime(path_str))


def get_file_last_modified_date_formatted(
    path: PathIn,
    *,
    format: str = "%Y-%m-%d %H:%M:%S",
) -> str:
    """Return the formatted last-modified date of a file."""
    return get_file_last_modified_date(path).strftime(format)


def get_file_size(path: PathIn) -> int:
    """Return the size of a file in bytes."""
    path_str = _get_path(path) or ""
    assert_file(path_str)
    return os.path.getsize(path_str)


def get_file_size_formatted(path: PathIn) -> str:
    """Return the file size using a human-readable unit."""
    return convert_size_bytes_to_string(get_file_size(path))
